import React from 'react'
import './Item.css'
import  Errorimage from '../Assets/new assets/Errorimage.jpg'

const Item = (props) => {
    return(
        <div className='item'>
          <img src={props.image} alt='' onError={(e) => e.target.src= Errorimage} />
          <p>{props.name}</p>

          <div className='items-prices'>
            <div className='new-price'>
                  ${props.new_price}
            </div>
            <div className='old-price'>
                  ${props.old_price}
            </div>
          </div>
        </div> 
)
}

export default Item
